const fourteenDaysAgo = new Date();
fourteenDaysAgo.setDate(fourteenDaysAgo.getDate() - 14);

const inactiveContacts = [];

for (const item of items) {

  const lastActivityDate = new Date(
    item.json["Last Activity Date"]
  );

  if (lastActivityDate < fourteenDaysAgo) {

    const diffDays = Math.floor(
      (new Date() - lastActivityDate) /
      (1000 * 60 * 60 * 24)
    );

    inactiveContacts.push({
      ...item.json,
      daysSinceContact: diffDays,
      needsAttention: true
    });

  }
}

// Return ONE item containing an array
return [
  {
    json: {
      inactiveContacts
    }
  }
];

const clients = $input.all().map(item => {

  const lastActivity = new Date(item.json["Last Activity Date"]);

  const days = Math.floor(
    (new Date() - lastActivity) /
    (1000 * 60 * 60 * 24)
  );

  return {
    name: `${item.json["First Name"] || ""} ${item.json["Last Name"] || ""}`.trim(),
    company: item.json["Company"] || "No company",
    days: days
  };
});

const top10 = clients.slice(0, 10);

const clientList = top10
  .map(c => `• ${c.name} | ${c.company} | ${c.days} days since last contact`)
  .join('\n');

return [{
  json: {
    count: clients.length,
    clientList
  }
}];

